function Get-HashUpper { param([Parameter(Mandatory=$true)][string]$Path) return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant() }
function Add-Test { param([Parameter(Mandatory=$true)][string]$Name,[Parameter(Mandatory=$true)][bool]$Passed,[string]$Detail=''); $safe=if([string]::IsNullOrWhiteSpace($Detail)){''}else{$Detail.Split([Environment]::NewLine)[0]}; [void]$tests.Add([ordered]@{name=$Name;passed=$Passed;detail=$safe}) }
function Run-Test { param([Parameter(Mandatory=$true)][string]$Name,[Parameter(Mandatory=$true)][scriptblock]$Action); try { & $Action; Add-Test $Name $true } catch { Add-Test $Name $false ([string]$_.Exception.Message) } }
function Assert-True { param([Parameter(Mandatory=$true)][bool]$Condition,[Parameter(Mandatory=$true)][string]$Message); if(-not $Condition){throw $Message} }
function Expect-Stop { param([Parameter(Mandatory=$true)][scriptblock]$Action,[Parameter(Mandatory=$true)][string]$Code); $ok=$false; try{& $Action|Out-Null}catch{ $ok=([string]$_.Exception.Message -match [regex]::Escape($Code)) }; if(-not $ok){throw ('EXPECTED_STOP_MISMATCH:'+ $Code)} }
function ConvertTo-WindowsArgument {
    param([Parameter(Mandatory=$true)][AllowEmptyString()][string]$Value)
    if($Value.Length -gt 0 -and $Value -notmatch '[\s"]'){return $Value}
    $b=[Text.StringBuilder]::new();[void]$b.Append('"');$slashes=0
    foreach($c in $Value.ToCharArray()){if($c -eq '\'){$slashes++;continue};if($c -eq '"'){[void]$b.Append(('\'*(2*$slashes+1)));[void]$b.Append('"');$slashes=0;continue};if($slashes -gt 0){[void]$b.Append(('\'*$slashes));$slashes=0};[void]$b.Append($c)}
    if($slashes -gt 0){[void]$b.Append(('\'*(2*$slashes)))};[void]$b.Append('"');return $b.ToString()
}
function Invoke-PS51Script {
    param([Parameter(Mandatory=$true)][string]$ScriptPath,[Parameter(Mandatory=$true)][string[]]$Arguments)
    $name='P5E_OWNER_ENDPOINT_ACCOUNT_FINGERPRINT';$old=[Environment]::GetEnvironmentVariable($name,'Process');[Environment]::SetEnvironmentVariable($name,$null,'Process')
    try{& $ps51Path -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $ScriptPath @Arguments 2>&1|Out-Null;$code=$LASTEXITCODE}finally{[Environment]::SetEnvironmentVariable($name,$old,'Process')};return [int]$code
}
function New-CaptureFixtureScript {
    $p=Join-Path $tempRoot 'capture-fixture.ps1'
    $t=@'
param([string]$Mode,[int]$Count=0)
switch($Mode) {
 'stdout' {[Console]::Out.Write('stdout');break}
 'stderr' {[Console]::Error.Write('stderr');break}
 'both' {[Console]::Out.Write('stdout');[Console]::Error.Write('stderr');break}
 'empty' {break}
 'exact' {$b=New-Object byte[] $Count;[Console]::OpenStandardOutput().Write($b,0,$b.Length);break}
 'invalid' {$b=[byte[]](0xff,0xfe,0xfd);[Console]::OpenStandardOutput().Write($b,0,$b.Length);break}
 'delayed' {[Console]::Out.Write('delayed');[Console]::Out.Flush();Start-Sleep -Milliseconds 250;break}
 'secret' {[Console]::Out.Write(('qa-'+'sentinel'));break}
 'nonzero' {[Console]::Out.Write('nonzero');exit 7}
 'timeout' {Start-Sleep -Seconds 120;break}
  'tree-grandchild' {Start-Sleep -Seconds 120;break}
  'tree-child' {$grandchild=Start-Process -FilePath $env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe -ArgumentList @('-NoLogo','-NoProfile','-NonInteractive','-File',$PSCommandPath,'tree-grandchild') -WindowStyle Hidden -PassThru;[IO.File]::AppendAllText($env:P5E_TREE_PID_FILE,[Environment]::NewLine+[string]$grandchild.Id);Start-Sleep -Seconds 120;break}
  'tree' {[IO.File]::WriteAllText($env:P5E_TREE_PID_FILE,'');$child=Start-Process -FilePath $env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe -ArgumentList @('-NoLogo','-NoProfile','-NonInteractive','-File',$PSCommandPath,'tree-child') -WindowStyle Hidden -PassThru;[IO.File]::AppendAllText($env:P5E_TREE_PID_FILE,[string]$child.Id);$deadline=(Get-Date).AddSeconds(5);while((Get-Date)-lt $deadline -and @([IO.File]::ReadAllLines($env:P5E_TREE_PID_FILE)).Count -lt 2){Start-Sleep -Milliseconds 50};[Console]::Out.Write([string]$child.Id);[Console]::Out.Flush();Start-Sleep -Seconds 120;break}
  'drain-hold' {Start-Sleep -Milliseconds 1000;$childInfo=[Diagnostics.ProcessStartInfo]::new();$childInfo.FileName=$env:WINDIR+'\System32\WindowsPowerShell\v1.0\powershell.exe';$childInfo.UseShellExecute=$false;$childInfo.CreateNoWindow=$true;$childInfo.Arguments='-NoLogo -NoProfile -NonInteractive -Command "Start-Sleep -Seconds 120"';$child=[Diagnostics.Process]::Start($childInfo);[IO.File]::WriteAllText($env:P5E_TREE_PID_FILE,[string]$child.Id);[Console]::Out.Write('drain-hold');[Console]::Out.Flush();exit 0}
}
'@
    [IO.File]::WriteAllText($p,$t,[Text.UTF8Encoding]::new($false));return $p
}
function Invoke-TextCaptureFixture {
    param([Parameter(Mandatory=$true)][string]$ScriptPath,[Parameter(Mandatory=$true)][string]$Mode,[int]$OutLimit=$stdoutLimit,[int]$ErrLimit=$stderrLimit,[int]$Timeout=5000,[int]$Count=0)
    $si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$ps51Path;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true
    $treePidFile=Join-Path $tempRoot ('tree-pids-'+[Guid]::NewGuid().ToString('N')+'.txt');$si.EnvironmentVariables['P5E_TREE_PID_FILE']=$treePidFile
    $args=@('-NoLogo','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',$ScriptPath,$Mode,[string]$Count);$si.Arguments=[string]::Join(' ',@($args|ForEach-Object{ConvertTo-WindowsArgument ([string]$_)}))
    $p=$null;$launch=$null
    try{$launch=[P5EProcessLauncher]::Start($si);$p=$launch.Process;$c=[P5EProcessTextCapture]::Capture($launch,$OutLimit,$ErrLimit,$Timeout,$null);return [pscustomobject]@{ExitCode=$c.ExitCode;CaptureBounded=[bool]$c.CaptureBounded;ContainmentVerified=[bool]$c.ContainmentVerified;ContainmentStatus=[string]$c.ContainmentStatus;CaptureErrorClass=[string]$c.CaptureErrorClass;StdoutDrainStatus=[string]$c.StdoutDrainStatus;StderrDrainStatus=[string]$c.StderrDrainStatus;TimedOut=[bool]$c.TimedOut;OutputTooLarge=[bool]$c.OutputTooLarge;StdoutTruncated=[bool]$c.StdoutTruncated;StderrTruncated=[bool]$c.StderrTruncated;StdoutByteLength=[long]$c.StdoutByteLength;StderrByteLength=[long]$c.StderrByteLength;StdoutText=[string]$c.Stdout;TreePidFile=$treePidFile;SecretWasCapturedInMemory=([string]$c.Stdout -match 'qa-sentinel')}}finally{if($null-ne$launch){$launch.Dispose()}elseif($null-ne$p){$p.Dispose()}}
}
function New-ReceiptObject {
    param([long]$IssuedAt=0L,[long]$ExpiresAt=0L)
    if($IssuedAt -eq 0L){$IssuedAt=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()-1000L};if($ExpiresAt -eq 0L){$ExpiresAt=$IssuedAt+60000L}
    return [ordered]@{schemaVersion='p5e.a43.owner-decision-receipt.v1';decisionId='qa-guard-decision-01';packetIdentifier=$packetIdentifier;serial=$serial;manifestSha256=(Get-HashUpper $manifestPath);commandSha256=(Get-HashUpper $commandPath);helperSha256=(Get-HashUpper $helperPath);exporterSha256=(Get-HashUpper $exporterPath);bridgeSha256=(Get-HashUpper $bridgePath);oneEventLimit=1;oneProviderCallLimit=1;scope=$scope;noRetry=$true;noFallback=$true;noRedispatch=$true;issuedAt=$IssuedAt;expiresAt=$ExpiresAt}
}
function Write-ReceiptFixture { param([Parameter(Mandatory=$true)]$Receipt,[string]$Name='');if([string]::IsNullOrWhiteSpace($Name)){$Name=[Guid]::NewGuid().ToString('N')};$p=Join-Path $tempRoot ('receipt-'+$Name+'.json');[IO.File]::WriteAllText($p,($Receipt|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));return [pscustomobject]@{Path=$p;Hash=(Get-HashUpper $p)} }
function Assert-ReceiptFixture { param([Parameter(Mandatory=$true)]$Fixture,[string]$ExpectedCode='');$pins=@{manifestSha256=(Get-HashUpper $manifestPath);commandSha256=(Get-HashUpper $commandPath);helperSha256=(Get-HashUpper $helperPath);exporterSha256=(Get-HashUpper $exporterPath);bridgeSha256=(Get-HashUpper $bridgePath)};$a={Read-P5EA43OwnerDecisionReceipt -ReceiptPath $Fixture.Path -ExpectedReceiptSha256 $Fixture.Hash -ExpectedPins $pins -ExpectedSerial $serial -ExpectedScope $scope};if([string]::IsNullOrWhiteSpace($ExpectedCode)){return & $a};Expect-Stop $a $ExpectedCode}

$fixtureScript=New-CaptureFixtureScript;$oldCommandText=Get-Content -Raw $oldCommandPath;$newCommandText=Get-Content -Raw $commandPath;$manifestText=Get-Content -Raw $manifestPath

