Run-Test 'GREEN-job-object-child-grandchild-and-delayed-close' {$a=Invoke-TextCaptureFixture $fixtureScript 'tree' -Timeout 5000;$b=Invoke-TextCaptureFixture $fixtureScript 'delayed' -Timeout 2000;$ids=@();if(Test-Path -LiteralPath $a.TreePidFile -PathType Leaf){$ids=@(Get-Content -LiteralPath $a.TreePidFile|ForEach-Object{[int]$v=0;if([int]::TryParse($_,[ref]$v)){$v}})};Assert-True ($ids.Count-ge 2) 'GRANDCHILD_FIXTURE_NOT_OBSERVED';$allExited=$true;foreach($descendantPid in $ids){$deadline=(Get-Date).AddSeconds(2);do{$alive=$null-ne(Get-Process -Id $descendantPid -ErrorAction SilentlyContinue);if(-not$alive){break};Start-Sleep -Milliseconds 50}while((Get-Date)-lt$deadline);if($alive){$allExited=$false};Assert-True (-not$alive) ('DESCENDANT_STILL_ALIVE_'+$descendantPid)};Assert-True ($a.ContainmentVerified-and$a.ContainmentStatus-eq 'TREE_EXIT_VERIFIED') 'DESCENDANT_TREE_NOT_VERIFIED';Assert-True ($b.ContainmentVerified-and$b.CaptureBounded) 'DELAYED_PIPE_NOT_DRAINED';$runtimeEvidence.suspendedJobLaunch=[ordered]@{status='PASS';containmentAttachedBeforeResume=$true;childDescendantVerification=if($allExited){'ALL_DESCENDANTS_EXITED'}else{'DESCENDANT_REMAINS'}}}
Run-Test 'GREEN-job-assign-failure-runtime-stop' {$si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$ps51Path;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.Arguments='-NoLogo -NoProfile -NonInteractive -Command "exit 0"';$p=[Diagnostics.Process]::new();$p.StartInfo=$si;try{Assert-True $p.Start() 'ASSIGN_FIXTURE_START_FAILED';$p.WaitForExit();$h=[P5EProcessTermination]::Attach($p);Assert-True ((-not $h.Attached) -and ([string]$h.AttachStatus -match 'ASSIGN|PROCESS|JOB')) 'ASSIGN_FAILURE_NOT_TYPED';$unknown=[P5EProcessTermination]::KillTree($p);Assert-True ((-not $unknown.Verified) -and $unknown.Status -eq 'EXTERNAL_PROCESS_STATE_UNKNOWN') 'ASSIGN_FAILURE_NOT_FAIL_CLOSED'}finally{$p.Dispose()}}
Run-Test 'GREEN-job-already-exited-race-runtime-verified' {$si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$ps51Path;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.Arguments='-NoLogo -NoProfile -NonInteractive -Command "Start-Sleep -Milliseconds 500; exit 0"';$p=[Diagnostics.Process]::new();$p.StartInfo=$si;try{Assert-True $p.Start() 'RACE_FIXTURE_START_FAILED';$h=[P5EProcessTermination]::Attach($p);Assert-True $h.Attached 'RACE_ATTACH_FAILED';$p.WaitForExit();$verified=[P5EProcessTermination]::VerifyAndClose($h,$p,1000);Assert-True ($verified.Verified-and$verified.Status-eq 'TREE_EXIT_VERIFIED') 'ALREADY_EXITED_RACE_NOT_VERIFIED'}finally{$p.Dispose()}}
Run-Test 'GREEN-job-drain-failure-preserves-exit-and-closes-tree' {$d=Invoke-TextCaptureFixture $fixtureScript 'drain-hold' -Timeout 2000;$drainIds=@();if(Test-Path -LiteralPath $d.TreePidFile -PathType Leaf){$drainIds=@(Get-Content -LiteralPath $d.TreePidFile|ForEach-Object{[int]$v=0;if([int]::TryParse($_,[ref]$v)){$v}})};Assert-True ($d.ExitCode-eq 0-and$d.CaptureErrorClass-eq 'TASK_WAIT_TIMEOUT'-and-not$d.CaptureBounded-and$d.ContainmentVerified) 'DRAIN_FAILURE_NOT_TYPED_OR_VERIFIED';Assert-True ($d.StdoutDrainStatus -ne 'DRAINED'-and$d.StderrDrainStatus -ne 'DRAINED') 'DRAIN_FAILURE_STATUS_COLLAPSED';$allExited=$true;foreach($descendantPid in $drainIds){$deadline=(Get-Date).AddSeconds(2);do{$alive=$null-ne(Get-Process -Id $descendantPid -ErrorAction SilentlyContinue);if(-not$alive){break};Start-Sleep -Milliseconds 50}while((Get-Date)-lt$deadline);if($alive){$allExited=$false};Assert-True (-not$alive) ('DRAIN_DESCENDANT_STILL_ALIVE_'+$descendantPid)};$runtimeEvidence.drainFailure=[ordered]@{status='PASS';processExitCode=[int]$d.ExitCode;captureErrorClass=[string]$d.CaptureErrorClass;stdoutDrainStatus=[string]$d.StdoutDrainStatus;stderrDrainStatus=[string]$d.StderrDrainStatus;captureBounded=[bool]$d.CaptureBounded;containmentVerified=[bool]$d.ContainmentVerified;descendantExited=$allExited};Assert-True ($newCommandText.IndexOf('CaptureErrorClass',[StringComparison]::Ordinal)-ge 0-and$newCommandText.IndexOf('STREAM_CAPTURE_FAILED',[StringComparison]::Ordinal)-ge 0-and$newCommandText.IndexOf('ProcessExitCode = $processExitCode',[StringComparison]::Ordinal)-ge 0) 'WRAPPER_DRAIN_FAILURE_BINDING_MISSING';$runtimeEvidence.wrapperBinding=[ordered]@{status='PASS';captureErrorChecked=$true;processExitPreserved=([int]$d.ExitCode -eq 0);typedWrapperStatus='STREAM_CAPTURE_FAILED'}}
Run-Test 'GREEN-job-containment-contract-no-parent-fallback' {$t=Get-Content -Raw $exporterPath;Assert-True ($t.IndexOf('ASSIGN_PROCESS_FAILED',[StringComparison]::Ordinal)-ge 0) 'ASSIGN_FAILURE_STATUS_MISSING';Assert-True ($t.IndexOf('EXTERNAL_PROCESS_STATE_UNKNOWN',[StringComparison]::Ordinal)-ge 0) 'UNKNOWN_TREE_STATUS_MISSING';Assert-True ($t.IndexOf('KillOnJobClose',[StringComparison]::Ordinal)-ge 0) 'JOB_FLAG_CONTRACT_MISSING';Assert-True ($t.IndexOf('CreateSuspended',[StringComparison]::Ordinal)-ge 0-and$t.IndexOf('P5EProcessLauncher',[StringComparison]::Ordinal)-ge 0) 'SUSPENDED_LAUNCH_CONTRACT_MISSING';Assert-True ($t.IndexOf('.Kill()',[StringComparison]::Ordinal)-lt 0) 'PARENT_ONLY_KILL_FALLBACK_PRESENT'}
Run-Test 'GREEN-capture-matrix-independent-caps-and-secret-not-emitted' {$a=Invoke-TextCaptureFixture $fixtureScript 'stdout';$b=Invoke-TextCaptureFixture $fixtureScript 'stderr';$c=Invoke-TextCaptureFixture $fixtureScript 'both';$d=Invoke-TextCaptureFixture $fixtureScript 'empty';$e=Invoke-TextCaptureFixture $fixtureScript 'exact' -OutLimit 64 -Count 64;$f=Invoke-TextCaptureFixture $fixtureScript 'exact' -OutLimit 64 -Count 65;$g=Invoke-TextCaptureFixture $fixtureScript 'invalid';$h=Invoke-TextCaptureFixture $fixtureScript 'secret';Assert-True ($a.StdoutByteLength-gt 0-and$b.StderrByteLength-gt 0-and$c.CaptureBounded) 'BASIC_CAPTURE_MATRIX_FAILED';Assert-True ($d.StdoutByteLength-eq 0-and$e.StdoutByteLength-eq 64-and-not$e.OutputTooLarge) 'EMPTY_OR_EXACT_CAP_FAILED';Assert-True ($f.OutputTooLarge-and$f.StdoutTruncated) 'CAP_PLUS_ONE_NOT_STOPPED';Assert-True ($g.CaptureBounded-and$g.ContainmentVerified-and$h.SecretWasCapturedInMemory) 'INVALID_OR_SENTINEL_FIXTURE_FAILED';Assert-True ($newCommandText.IndexOf('capture.Stdout',[StringComparison]::Ordinal)-ge 0-and$newCommandText.IndexOf('P5E_OUTPUT_TOO_LARGE',[StringComparison]::Ordinal)-lt 0) 'OUTER_RAW_RETENTION_CONTRACT_FAILED';$ht=Get-Content -Raw $helperPath;Assert-True ($ht.IndexOf('New-P5ESafeInstrumentationEvidenceText',[StringComparison]::Ordinal)-ge 0) 'SAFE_INSTRUMENTATION_SUMMARY_MISSING';Assert-True ($ht.IndexOf('Write-P5EUtf8NoBom -Path $stdoutPath -Text $safeStdout.Text',[StringComparison]::Ordinal)-lt 0) 'RAW_INSTRUMENTATION_WRITE_PRESENT'}

Run-Test 'GREEN-pm-path-classifier-matrix-and-mutation-fail-closed' {
    function Run-PM([string]$o,[string]$e,[int]$x,[bool]$large=$false){Get-P5EPackagePathClassification -Run ([pscustomobject]@{LaunchCount=1L;TimedOut=$false;ExitCode=$x;Stdout=$o;Stderr=$e;RedactionViolation=$false;OutputTooLarge=$large;CaptureBounded=$true;ContainmentVerified=$true}) -PackageName 'com.ml.tblandroidtxt'}
    Assert-True ((Run-PM 'package:/data/app/com.ml.tblandroidtxt-abc/base.apk' '' 0).Classification-eq 'PACKAGE_PRESENT') 'PM_PRESENT_FAILED'
    Assert-True ((Run-PM '' 'unknown package: com.ml.tblandroidtxt' 1).Classification-eq 'PACKAGE_NOT_FOUND') 'PM_NOT_FOUND_FAILED'
    Assert-True ((Run-PM '' 'device offline' 1).Classification-eq 'DEVICE_UNAVAILABLE') 'PM_OFFLINE_FAILED'
    Assert-True ((Run-PM '' 'device unauthorized' 1).Classification-eq 'DEVICE_UNAVAILABLE') 'PM_UNAUTHORIZED_FAILED'
    Assert-True ((Run-PM '' "can't find service: package" 1).Classification-eq 'PM_SERVICE_FAILURE') 'PM_SERVICE_FAILED'
    Assert-True ((Run-PM 'package:malformed' '' 0).Classification-eq 'MALFORMED_RESPONSE') 'PM_MALFORMED_FAILED'
    Assert-True ((Run-PM ('package:/data/app/com.ml.tblandroidtxt-a/base.apk'+[Environment]::NewLine+'package:/data/app/com.ml.tblandroidtxt-b/base.apk') '' 0).Classification-eq 'MALFORMED_RESPONSE') 'PM_DUPLICATE_FAILED'
    Assert-True ((Run-PM 'package:/data/app/other-abc/base.apk' '' 0).Classification-eq 'MALFORMED_RESPONSE') 'PM_WRONG_PACKAGE_FAILED'
    Assert-True ((Run-PM '' 'unclassified native failure' 1).Classification-eq 'UNKNOWN_NONZERO') 'PM_UNKNOWN_NOT_FAIL_CLOSED'
    Assert-True ((Run-PM '' 'unknown package: com.ml.tblandroidtxt' 1 $true).Classification-eq 'UNKNOWN_NONZERO') 'PM_TRUNCATION_FALSE_ACCEPT'
}

Run-Test 'GREEN-owner-receipt-positive-and-negative-matrix' {
    $now=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();$p=Write-ReceiptFixture (New-ReceiptObject ($now-1000L) ($now+60000L)) 'positive';$r=Assert-ReceiptFixture $p;Assert-True ($r.DecisionId-eq 'qa-guard-decision-01'-and$r.Serial-eq $serial) 'RECEIPT_POSITIVE_FAILED'
    Expect-Stop {Read-P5EA43OwnerDecisionReceipt -ReceiptPath (Join-Path $tempRoot 'missing.json') -ExpectedReceiptSha256 $p.Hash -ExpectedPins @{} -ExpectedSerial $serial -ExpectedScope $scope} 'P5E_OWNER_RECEIPT_MISSING_STOP'
    Expect-Stop {Read-P5EA43OwnerDecisionReceipt -ReceiptPath $p.Path -ExpectedReceiptSha256 ('0'*64) -ExpectedPins @{} -ExpectedSerial $serial -ExpectedScope $scope} 'P5E_OWNER_RECEIPT_HASH_MISMATCH_STOP'
