    $raceRoot=Join-Path $tempRoot 'race-root';[void](New-Item -ItemType Directory -Path $raceRoot);$raceScript=Join-Path $tempRoot 'race-contender.ps1';$race=@'
param([string]$Guard,[string]$Root,[string]$Decision,[string]$Hash)
. $Guard -LibraryOnly
try{$r=Reserve-P5EA43OwnerDecisionEvent -EvidenceRoot $Root -DecisionId $Decision -ReceiptSha256 $Hash;Write-Output 'WIN'}catch{Write-Output ([string]$_.Exception.Message)}
'@;[IO.File]::WriteAllText($raceScript,$race,[Text.UTF8Encoding]::new($false));$ps=@()
    foreach($n in 1..2){$si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$ps51Path;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true;$a=@('-NoLogo','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',$raceScript,$guardPath,$raceRoot,'race-simultaneous',$hashC);$si.Arguments=[string]::Join(' ',@($a|ForEach-Object{ConvertTo-WindowsArgument ([string]$_)}));$p=[Diagnostics.Process]::new();$p.StartInfo=$si;[void]$p.Start();$ps+=$p}
    $outs=@();foreach($p in $ps){$p.WaitForExit(10000)|Out-Null;$outs+=$p.StandardOutput.ReadToEnd();$p.Dispose()};$wins=@($outs|Where-Object{$_.Trim()-eq 'WIN'}).Count;$eventDirs=@(Get-ChildItem -LiteralPath $raceRoot -Directory -Force|Where-Object{$_.Name -like 'raw-live-a43-preauth-*'});Assert-True ($wins-eq 1-and$eventDirs.Count-eq 1) 'ATOMIC_RACE_NOT_ONE_WINNER'
}
